  'reading-one-headline.match-where-next.prompt': 'Ya conoces las palabras básicas. Relaciona cada pregunta que aún puedas tener con la parte del curso que la responde.',
  'reading-one-headline.match-where-next.instructions': 'Elige un término y luego su definición',
